<?php
ob_start();session_id('nstAli'.bin2hex(random_bytes(8)));session_start();$cookie='PHPSESSID='.session_id();session_write_close();function callAli($path,$cookie,$body=null,$csrf=''){$h=curl_init('http://localhost/api/index.php/ali/'.$path);curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10,CURLOPT_COOKIE=>$cookie,CURLOPT_HTTPHEADER=>['Content-Type: application/json','X-Ali-CSRF: '.$csrf]]);if($body!==null)curl_setopt_array($h,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($body)]);$raw=curl_exec($h);$code=curl_getinfo($h,CURLINFO_HTTP_CODE);curl_close($h);return [$code,json_decode($raw,true)];}function checkAli($ok,$msg){if(!$ok)throw new Exception($msg);}try{[$code]=callAli('config',$cookie);checkAli($code===401,'unauth');session_start();$_SESSION['user']='vendedor-prueba';session_write_close();[$code,$data]=callAli('config',$cookie);checkAli($code===403,'unknown ERP user denied');[$code]=callAli('config',$cookie,[]);checkAli($code===403,'role');session_start();$_SESSION['user']='superadmin';session_write_close();[$code,$data]=callAli('config',$cookie);checkAli($code===200&&$data['superadmin'],'superadmin');[$code]=callAli('config',$cookie,[]);checkAli($code===403,'csrf');[$code]=callAli('config',$cookie,['model'=>'bad model'], $data['csrf']);checkAli($code===422,'validation');if(!$data['configured']){[$code]=callAli('producto',$cookie,['id'=>1],$data['csrf']);checkAli($code===409,'missing key');}echo "PASS ALI API auth, role, CSRF, model validation and no key exposure. No settings saved; no OpenAI calls.\n";}finally{session_start();$_SESSION=[];session_destroy();ob_end_flush();}
